/**
 * Structural type for the underlying call session implementation (hidden from public typings).
 */
interface IInternalCallSession {
    getCallId(): string;
    getState(): unknown;
    getCallType(): unknown;
    getMediaType(): unknown;
    getUserList(): Array<{
        userId: string;
        state: unknown;
        cameraEnable: boolean;
        microphoneEnable: boolean;
    }>;
    getCreatorUserId(): string;
    getInviterUserId(): string;
}

/**
 * Call session: read-only information for the current call.
 */

/** User information during a call */
interface NCCallUser {
    /**
     * User ID
     */
    userId: string;
    /**
     * User state in this call
     */
    userState: NCCallUserState;
    /**
     * Whether camera is on
     */
    isCameraEnabled: boolean;
    /**
     * Whether microphone is on
     */
    isMicrophoneEnabled: boolean;
}
declare class NCCallSession {
    private readonly _session;
    private readonly _currentUserId;
    constructor(_session: IInternalCallSession, _currentUserId: string);
    /** Get call ID */
    getCallId(): string;
    /** Get call state */
    getCallState(): NCCallState;
    /** Get call type (1:1 / group, etc.) */
    getCallType(): NCCallType;
    /** Get media type (audio / audio+video) */
    getMediaType(): NCCallMediaType;
    /** Get remote participant list */
    getRemoteParticipants(): NCCallUser[];
    /** Get caller user id */
    getCallerUserId(): string;
    /** Get inviter user id */
    getInviterUserId(): string;
}

